      "arFull": "كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوْحٍ وَّعَادٌ وَّفِرْعَوْنُ ذُو الْاَوْتَادِ ۟ۙ",
      "ur": "ان سے پہلے بھی قوم نوح اور عاد اور میخوں والے فرعون[1] نے جھٹلایا تھا.",
      "en": "The people of Noah denied before them, and [the tribe of] ʿAad and Pharaoh, the owner of stakes,[1322]",
      "footnotesUr": "[1] فرعون کو میخوں والا اس لیے کہا کہ وہ ظالم جب کسی پر غضب ناک ہوتا تو اس کے ہاتھوں، پیروں اور سر میں میخیں گاڑ دیتا، یا اس سے مقصد بطور استعارہ اس کی قوت وشوکت اور مضبوط حکومت کا اظہار ہے یعنی میخوں سے جس طرح کسی چیز کو مضبوط کر دیاجاتا ہے، اس کا لشکر جرار اور اس کے پیروکار بھی اس کی سلطنت کی قوت واستحکام کا باعث تھے۔",
