      "number": 22,
      "arFull": "اِذْ دَخَلُوْا عَلٰی دَاوٗدَ فَفَزِعَ مِنْهُمْ قَالُوْا لَا تَخَفْ ۚ خَصْمٰنِ بَغٰی بَعْضُنَا عَلٰی بَعْضٍ فَاحْكُمْ بَیْنَنَا بِالْحَقِّ وَلَا تُشْطِطْ وَاهْدِنَاۤ اِلٰی سَوَآءِ الصِّرَاطِ ۟",
      "ur": "جب یہ (حضرت) داؤد (علیہ السلام) کے پاس پہنچے، پس یہ ان سے ڈر گئے[1] ، انہوں نے کہا خوف نہ کیجئے! ہم دو فریق مقدمہ ہیں، ہم میں سے ایک نے دوسرے پر زیادتی کی ہے، پس آپ ہمارے درمیان حق کے ساتھ فیصلہ کر دیجئے اور ناانصافی نہ کیجئے اور ہمیں سیدھی راه بتا دیجئے.[2]",
      "en": "When they entered upon David and he was alarmed by them? They said, \"Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path.",
      "footnotesUr": "[1] ڈرنے کی وجہ صاف ظاہر ہے کہ ایک تو وہ دروازے کے بجائےعقب سے دیوار چڑھ کر اندر آئے۔ دوسرے، انہوں نے اتنا بڑا اقدام کرتے ہوئے بادشاہ وقت سے کوئی خوف محسوس نہیں کیا۔ ظاہری اسباب کے مطابق خوف والی چیز سے خوف کھانا، انسان کا ایک طبعی تقاضا ہے۔ یہ منصب وکمال نبوت کے خلاف ہے نہ توحید کے منافی۔ توحید کے منافی غیر اللہ کا وہ خوف ہے جو ماورائے اسباب ہو۔\n[2] آنے والوں نے تسلی دی کہ گھبرانے کی ضرورت نہیں ہے، ہمارے درمیان ایک جھگڑا ہے، ہم آپ سے فیصلہ کرانے آئے ہیں، آپ حق کے ساتھ فیصلہ بھی فرمائیں اور سیدھے راستے کی طرف ہماری رہنمائی بھی۔",
      "footnotesEn": null,
