      "arFull": "كِتٰبٌ اَنْزَلْنٰهُ اِلَیْكَ مُبٰرَكٌ لِّیَدَّبَّرُوْۤا اٰیٰتِهٖ وَلِیَتَذَكَّرَ اُولُوا الْاَلْبَابِ ۟",
