      "arFull": "وَاذْكُرْ عَبْدَنَاۤ اَیُّوْبَ ۘ اِذْ نَادٰی رَبَّهٗۤ اَنِّیْ مَسَّنِیَ الشَّیْطٰنُ بِنُصْبٍ وَّعَذَابٍ ۟ؕ",
