      "footnotesUr": "[1] حضرت ایوب (عليه السلام) کی بیماری اور اس میں ان کا صبر مشہور ہے۔ جس کےمطابق اللہ تعالیٰ نے اہل ومال کی تباہی اور بیماری کے ذریعے سے ان کی آزمائش کی، جس میں وہ کئی سال مبتلا رہے۔ حتیٰ کہ صرف ایک بیوی ان کے ساتھ رہ گئی جو صبح وشام ان کی خدمت بھی کرتی اور ان کو کہیں کام کاﺝ کرکے بقدر کفاف رزق کا انتظام بھی کرتی۔ یہاں پر متعدد تفسیری روایات کا ذکر کیا جاتا ہے، مگر اس میں سے کتنا کچھ صحیح ہے اور کتنا نہیں، اسے معلوم کرنے کا کوئی مستند ذریعہ نہیں۔ نُصْبٍ سے جسمانی تکالیف اور عذاب سے مالی ابتلا مراد ہے۔ اس کی نسبت شیطان کی طرف اس لئے کی گئی ہے دراں حالیکہ سب کچھ کرنے والا صرف اللہ ہی ہے، کہ ممکن ہے شیطان کے وسوسے ہی کسی ایسے عمل کا سبب بنے ہوں جس پر یہ آزمائش آئی یا پھر بطور ادب کے ہے کہ خیر کو اللہ تعالیٰ کی طرف اور شر کو اپنی یا شیطان کی طرف منسوب کیا جاتا ہے۔",
