      "number": 59,
      "arFull": "هٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ ۚ لَا مَرْحَبًا بِهِمْ ؕ اِنَّهُمْ صَالُوا النَّارِ ۟",
      "ur": "یہ ایک قوم ہے جو تمہارے ساتھ (آگ میں) جانے والی ہے[1] ، کوئی خوش آمدید ان کے لئے نہیں ہے[2] یہی تو جہنم میں جانے والے ہیں.[3]",
      "en": "[Its inhabitants will say], \"This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire.\"",
      "footnotesUr": "[1] جہنم کے دروازوں پر کھڑے فرشتے، ائمۂ کفر اور پیشوایان ضلالت سے کہیں گے، جب پیروکار قسم کے کافر جہنم میں جائیں گے۔ یا ائمۂ کفر وضلالت آپس میں یہ بات، پیرو کاروں کی طرف اشارہ کرکے کہیں گے۔\n[2] یہ لیڈر، جہنم میں داخل ہونے والے کافروں کے لئے، فرشتوں کے جواب میں یا آپس میں کہیں گے۔ رَحْبَةٌ کے معنی وسعت وفراخی کے ہیں۔ مرحبا یہ كَلِمَةُ تَرْحِيبٍ یعنی خیر مقدمی الفاظ ہیں جو آنے والے مہمان کے استقبال کے وقت کہے جاتے ہیں۔ لا مَرْحَبًا اس کے برعکس ہے۔\n[3] یہ ان کا خیر مقدم نہ کرنے کی علت ہے۔ یعنی ان کے اور ہمارے مابین کوئی وجہ امتیاز نہیں ہے، یہ بھی ہماری طرح جہنم میں داخل ہو رہے ہیں اور جس طرح ہم عذاب کے مستحق ٹھہرے ہیں، یہ بھی عذاب جہنم کے مستحق قرار پائے ہیں۔",
      "footnotesEn": null,
