      "arFull": "اِذْ قَالَ رَبُّكَ لِلْمَلٰٓىِٕكَةِ اِنِّیْ خَالِقٌۢ بَشَرًا مِّنْ طِیْنٍ ۟",
      "ur": "جبکہ آپ کے رب نے فرشتوں سے ارشاد فرمایا[1] کہ میں مٹی سے انسان کو پیدا[2] کرنے واﻻ ہوں.",
      "en": "[So mention] when your Lord said to the angels, \"Indeed, I am going to create a human being from clay.",
      "footnotesUr": "[1] یہ قصہ اس سے قبل سورۂ بقرہ، سورۂ اعراف، سورۂ حجر، سورۂ بنی اسرائیل اور سورۂ کہف میں بیان ہو چکا ہے۔ اب اسے یہاں بھی اجمالاً بیان کیا جا رہا ہے۔\n[2] یعنی ایک جسم، جنس بشر سے بنانے والا ہوں۔ انسان کو بشر، زمین سے اس کی مباشرت کی وجہ سے کہا۔ یعنی زمین سے ہی اس کی ساری وابستگی ہے اور وہ سب کچھ اسی زمین پر کرتا ہے۔ یا اس کے لئے وہ بادی البشرۃ ہے۔ یعنی اس کا جسم یا چہرہ ظاہر ہے۔",
      "footnotesEn": null,
