      "en": "Except Iblees;[1336] he was arrogant and became among the disbelievers.",
      "footnotesUr": "[1] اگر ابلیس کو صفات ملائکہ سے متصف مانا جائے تو یہ استثنا متصل ہوگا یعنی ابلیس اس حکم سجدہ میں داخل ہوگا، بصورت دیگر یہ استثنا منقطع ہے یعنی وہ اس حکم میں داخل نہیں تھا لیکن آسمان پر رہنے کی وجہ سے اسے بھی حکم دیا گیا۔ مگر اس نے تکبر کی وجہ سے انکار کر دیا۔\n[2] یہ کان صَارَ کے معنی میں ہے یعنی اللہ تعالیٰ کے حکم کی مخالفت اور اس کی اطاعت سے استکبار کی وجہ سے وہ کافر ہو گیا۔ یا اللہ کے علم میں وہ کافر تھا۔",
