      "arFull": "قُلْ مَاۤ اَسْـَٔلُكُمْ عَلَیْهِ مِنْ اَجْرٍ وَّمَاۤ اَنَا مِنَ الْمُتَكَلِّفِیْنَ ۟",
      "ur": "کہہ دیجئے کہ میں تم سے اس پر کوئی بدلہ طلب نہیں کرتا[1] اور نہ میں تکلف کرنے والوں میں سے ہوں.[2]",
      "en": "Say, [O Muḥammad], \"I do not ask you for it [i.e., the Qur’ān] any payment, and I am not of the pretentious.",
      "footnotesUr": "[1] یعنی اس دعوت وتبلیغ سے میرا مقصد صرف امتثال امر الٰہی ہے، دنیا کمانا نہیں۔\n[2] یعنی اپنی طرف سے گھڑ کر اللہ کی طرف ایسی بات منسوب کر دوں جو اس نے نہ کہی ہو یا میں تمہیں ایسی بات کی طرف دعوت دوں جس کا حکم اللہ نے مجھے نہ دیا ہو۔ بلکہ کوئی کمی بیشی کیے بغیر اللہ کے احکام تم تک پہنچا رہا ہوں۔ حضرت عبداللہ ابن مسعود ! فرماتے تھے، جس کو کسی بات کا علم نہ ہو، اس کی بابت اسے کہہ دینا چاہئیے، اللہ اعلم یہ کہنا بھی علم ہی ہے، اس لئے کہ اللہ نے اپنے پیغمبر کو کہا، فرما دیجئے «وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ» (ابن کثیر) علاوہ ازیں اس سے عام معاملات زندگی میں بھی تکلف وتصنع سے اجتناب کا حکم معلوم ہوتا ہے۔ جیسے نبی (صلى الله عليه وسلم) نے فرمایا «نُهِينَا عَنِ التَّكَلُّفِ» (صحيح بخاري، نمبر 7293) ہمیں تکلف سے منع کیا گیا ہے۔ حضرت سلمان (رضي الله عنه) کہتے ہیں «نَهَانَا رَسُولُ اللهِ (صلى الله عليه وسلم) أَنَّ نَتَكَلَّفَ لِلضَّيْفِ» (صحيح الجامع الصغير 9871) ہمیں رسول اللہ (صلى الله عليه وسلم) نے مہمان کے لئے تکلف کرنے سے منع فرمایا ہے۔ اس سے معلوم ہوا کہ لباس، خوراک، رہائش اور دیگر معاملات میں تکلﻔات، جو آج کل معیار زندگی بلند کرنے کے عنوان سے، اصحاب حیثیت کا شعار اور وطیرہ بن چکا ہے، اسلامی تعلیمات کے خلاف ہے۔ اسلام میں سادگی اور بے تکلﻔی اختیار کرنے کی تلقین وترغیب ہے۔",
